import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as i,c as n,o,ag as s,G as r}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const y=JSON.parse('{"title":"T3 Code 上手：装好它，跑通第一个线程，从手机继续","description":"T3 Code 是一个开源的本地应用，自己不带模型，专门驱动你电脑上已装好并登录的 coding agent，让它们共用一个界面、一套审批和改动查看，并支持人离开电脑后从手机继续。本页带你装好它、跑通第一个线程、学会权限模式与远程访问，并讲清三条安全边界。","frontmatter":{"title":"T3 Code 上手：装好它，跑通第一个线程，从手机继续","description":"T3 Code 是一个开源的本地应用，自己不带模型，专门驱动你电脑上已装好并登录的 coding agent，让它们共用一个界面、一套审批和改动查看，并支持人离开电脑后从手机继续。本页带你装好它、跑通第一个线程、学会权限模式与远程访问，并讲清三条安全边界。","domain":"product","tags":["coding-agent","agent-workspace","remote-access"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"zh/products/t3code/t3code.md","filePath":"zh/products/t3code/t3code.md","lastUpdated":1795764761000}'),d={name:"zh/products/t3code/t3code.md"};function l(h,t,p,c,g,k){const e=i("DocDiagram");return o(),n("div",null,[t[0]||(t[0]=s("",48)),r(e,{src:"/diagrams/t3code-thread-lifecycle.svg",alt:"这张时序图按编号回答两个问题：你在界面里发出一句话之后，它经过哪些环节才变成 agent 进程的一次执行；agent 要权限时，这个请求又是怎么回到你面前、再把你的决定送回去的。图里有六列。第一列是用户，也就是桌面、网页或手机客户端。中间三列同属 T3 Code 服务器：Orchestrator 是编排器，只算出事件和副作用，不做输入输出；EventSink 负责落库；EffectWorker 在提交之后执行副作用。第五列是 Provider 适配器，它把 T3 Code 的操作与事件翻译成各家 agent 的协议。第六列是外部 agent 进程，例如 Claude Code 或 Codex 的命令行进程。实线是命令或调用，虚线是事件、通知与返回。第一步，用户经已认证的 RPC 发出一条命令。第二步，Orchestrator 算出事件，以及一个启动 provider 轮次的副作用。第三步，EventSink 在一个数据库事务里写入事件、投影、命令回执和待执行的副作用；提交之后才通知订阅者，客户端因此显示出你的消息。第四步，EffectWorker 在提交后取出副作用，调用 Provider 适配器。第五步，适配器带着与权限模式对应的策略，调用外部 agent 进程的 startTurn，agent 开始执行。第六步，agent 进程产生事件，适配器把它翻译成统一事件，作为命令送回 Orchestrator 落库，再推送给客户端，显示文本增量和工具调用。第七步，agent 进程请求权限时，适配器先按权限模式判断：allow 或 deny 就直接答复，ask 才生成一条待处理请求，也就是 runtime_request，并显示在对话里。第八步，用户批准或拒绝，客户端再发一条回应运行时请求的命令；Orchestrator 把请求记为已解决并落库；EffectWorker 调用适配器的 respondToRuntimeRequest，把决定送回 agent 进程，agent 继续。三条要记住的关系：界面从不直接碰 agent，所有客户端都经已认证的 RPC 连到服务器；各家 provider 的差异被关在适配器后面，编排器和界面只读适配器声明的能力；审批和消息走同一条通道，两边都先落库再送达，所以在手机上点批准和在电脑上点批准是同一套流程。本图省略了具体的界面与按钮、模型推理的内部步骤、T3 Connect 中继（它不在业务数据的路径上），T3 Code 自己不运行模型。",width:1020}),t[1]||(t[1]=s("",115))])}const F=a(d,[["render",l]]);export{y as __pageData,F as default};
